var { TypeDB, SessionType, TransactionType } = require("typedb-client")
const { log, i18n, events, exec, util } = require("@node-red/util");

let _clients = {}
let _sessions = {}
let client_ids = new Set()

const typedb_path = "[TypeDB/runtime/lib/typedb/index.js @openSession()]::"
async function connectClient(client) {
    try {
        // http://localhost:1729
        let coreClient = TypeDB.coreClient(client)
        let client_id = Math.floor(Math.random() * 100)
        while (client_ids.has(client_id)) {
            client_id = Math.floor(Math.random() * 100)
        }
        _clients = {
            ..._clients, [client_id]: coreClient
        }
        log.info("[TypeDB] Successfully connected to TypeDB; client now available for future sessions and transactions");
        return client_id
    } catch (exception) {
        console.log(exception)
        throw exception
    }
}

function getClient(client_id) {
    if (_client !== "") {
        return _client
    } else {
        return false
    }
}

async function openSession(client_id, database, sessionRequest) {
    try {
        let client = ""
        if (_clients[client_id]) {
            client = _clients[client_id]
            let sessionType = sessionRequest.toLowerCase() === "data" ? SessionType.DATA : sessionType
            sessionType = sessionRequest.toLowerCase() === "schema" ? SessionType.SCHEMA : sessionType
            _sessions = { ..._sessions, [client_id]: await client.session(database, sessionType) }
            log.info("[TypeDB] Opened session for database " + database + " and session of type " + sessionRequest + " for client " + client_id)
            return _sessions[client_id]
        }
    } catch (exception) {
        log.warn(typedb_path + "Error in opening session for database " + database + " and session of type" + sessionRequest + "  for client " + client_id);
        throw exception
    }
}

async function closeSession(client_id) {
    try {
        if (_sessions[client_id] !== "" && _sessions[client_id] !== undefined) {
            if (_sessions[client_id].isOpen()) {
                log.info(typedb_path + " Session for " + client_id + " remains open... will attempt to close");
                await _sessions[client_id].close()
                delete _sessions[client_id]
                log.info(typedb_path + " Successfully closed TypeDB.session for " + client_id)
            }
        }
    } catch (exception) {
        log.warn(typedb_path + "Error while closing TypeDB.session " + client_id)
        console.log(exception)
        throw exception
    }
}

async function closeClient(client_id) {
    try {
        if (_clients[client_id] !== "" && _clients[client_id].isOpen()) {
            await _clients[client_id].close()
            delete _clients[client_id]
            client_ids.delete(client_id)
            log.info(typedb_path + " Successfully closed TypeDB.coreClient for client " + client_id)
        } else {
            if (_clients[client_id]) {
                delete _clients[client_id]
                client_ids.delete(client_id)
            }
        }
    } catch (exception) {
        log.warn(typedb_path + "Error while closing TypeDB.coreClient " + client_id)
        if (_clients[client_id]) {
            await _clients[client_id].close()
            delete _clients[client_id]
            client_ids.delete(client_id)
        }
        console.log(exception)
        throw exception
    }

}

async function openTransaction(client_id, transactionProvided) {
    try {
        let client = ""
        if (_clients[client_id] && _sessions[client_id]) {
            let session = _sessions[client_id]
            // console.log(session)
            let transactionType = transactionProvided.toLowerCase() === "write" ? TransactionType.WRITE : transactionProvided
            transactionType = transactionProvided.toLowerCase() === "read" ? TransactionType.READ : transactionProvided
            let transaction = await session.transaction(transactionType)
            // console.log(transaction)
            return transaction
        }
    } catch (exception) {
        log.warn(typedb_path + "Error in opening transaction");
        throw exception
    }

}

module.exports = {
    init: function init(runtime) {
        console.log("initializing api for typedb")
    },
    connectClient: connectClient,
    openSession: openSession,
    openTransaction: openTransaction,
    closeSession: closeSession,
    closeClient, closeClient,
}